

# This file was *autogenerated* from the file sagemath/check/160_pauli_matrix_products/check_01_pauli_products.sage
from sage.all_cmdline import *   # import sage library

_sage_const_0p0 = RealNumber('0.0'); _sage_const_1p0 = RealNumber('1.0'); _sage_const_1 = Integer(1); _sage_const_0 = Integer(0); _sage_const_1en12 = RealNumber('1e-12'); _sage_const_0p5 = RealNumber('0.5')# ---------------------------------------------------------
# <pauli_matrix_products>（006_Z_Y_anticommutation.mjs / Z_Y_anticommutation_000a_claim_pauli_matrix_products）
#
# 主張:
#   sigma^x sigma^x = sigma^y sigma^y = sigma^z sigma^z = I
#   sigma^z sigma^x = - sigma^x sigma^z
#   sigma^y sigma^x = - sigma^x sigma^y
#   sigma^y sigma^z = - sigma^z sigma^y
#
# 独立経路:
#   (a) この check の中で literal な成分から Pauli 行列を作り直し、共有ライブラリ
#       operators.sage の PAULI と一致することを確かめる（ライブラリ側の写し間違い検出）。
#   (b) 16 通りの積 sigma^a sigma^b を、閉じた公式
#           sigma^a sigma^b = delta_{ab} I + i sum_c eps_{abc} sigma^c
#       と突き合わせる。この公式は本文の 6 式より強い（本文の 6 式は公式の系）。
#       成分計算（本文の経路）と Levi-Civita 公式（独立な経路）の 2 経路の一致を見る。
#   (c) そのうえで本文の 6 式そのものを確かめる。
#   (d) 反例探し: 「どの 2 つの相異なる Pauli 行列も可換ではない」「sigma^a sigma^b は
#       a != b のとき I の定数倍ではない」ことを確かめ、6 式が自明に成り立っているのでは
#       ないことを示す。
# ---------------------------------------------------------
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in dir() else '.'
load(os.path.join(_dir, '../../_shared/operators.sage'))

import numpy as np

IU = complex(_sage_const_0p0 , _sage_const_1p0 )

rep = CheckReport("<pauli_matrix_products>: Pauli 行列の積")

# --- (a) literal な定義（本文 statement の成分をそのまま書き写したもの） ---
loc = {
    '0': np.array([[_sage_const_1 , _sage_const_0 ], [_sage_const_0 , _sage_const_1 ]], dtype=complex),
    'x': np.array([[_sage_const_0 , _sage_const_1 ], [_sage_const_1 , _sage_const_0 ]], dtype=complex),
    'y': np.array([[_sage_const_0 , -IU], [IU, _sage_const_0 ]], dtype=complex),
    'z': np.array([[_sage_const_1 , _sage_const_0 ], [_sage_const_0 , -_sage_const_1 ]], dtype=complex),
}
for a in ['0', 'x', 'y', 'z']:
    rep.close(loc[a], PAULI[a], "(a) operators.sage の PAULI['%s'] と本文の成分が一致" % a)

# --- (b) Levi-Civita 公式との突き合わせ（独立な閉形式） ---
LEVI = {
    ('x', 'y', 'z'): _sage_const_1p0 , ('y', 'z', 'x'): _sage_const_1p0 , ('z', 'x', 'y'): _sage_const_1p0 ,
    ('x', 'z', 'y'): -_sage_const_1p0 , ('z', 'y', 'x'): -_sage_const_1p0 , ('y', 'x', 'z'): -_sage_const_1p0 ,
}
axes = ['x', 'y', 'z']
for a in axes:
    for b in axes:
        formula = (_sage_const_1p0  if a == b else _sage_const_0p0 ) * loc['0']
        for c in axes:
            e = LEVI.get((a, b, c), _sage_const_0p0 )
            if e != _sage_const_0p0 :
                formula = formula + IU * e * loc[c]
        rep.close(loc[a] @ loc[b], formula,
                  "(b) sigma^%s sigma^%s = delta I + i eps sigma" % (a, b))

# --- (c) 本文の 6 式 ---
for a in axes:
    rep.close(loc[a] @ loc[a], loc['0'], "(c) sigma^%s sigma^%s = I" % (a, a))

rep.close(loc['z'] @ loc['x'], -(loc['x'] @ loc['z']),
          "(c) sigma^z sigma^x = - sigma^x sigma^z")
rep.close(loc['y'] @ loc['x'], -(loc['x'] @ loc['y']),
          "(c) sigma^y sigma^x = - sigma^x sigma^y")
rep.close(loc['y'] @ loc['z'], -(loc['z'] @ loc['y']),
          "(c) sigma^y sigma^z = - sigma^z sigma^y")

# --- (d) 反例探し: 6 式が自明ではないことの確認 ---
for (a, b) in [('x', 'y'), ('y', 'z'), ('z', 'x')]:
    c = comm(loc[a], loc[b])
    rep.truth(float(np.max(np.abs(c))) > _sage_const_1p0 ,
              "(d) [sigma^%s, sigma^%s] != 0（可換ではない: max|.|=%.3f）"
              % (a, b, float(np.max(np.abs(c)))))
    p = loc[a] @ loc[b]
    # p が I のスカラー倍なら、非対角成分が 0 かつ対角成分が等しい
    is_scalar = (abs(p[_sage_const_0 , _sage_const_1 ]) < _sage_const_1en12  and abs(p[_sage_const_1 , _sage_const_0 ]) < _sage_const_1en12 
                 and abs(p[_sage_const_0 , _sage_const_0 ] - p[_sage_const_1 , _sage_const_1 ]) < _sage_const_1en12 )
    rep.truth(not is_scalar,
              "(d) sigma^%s sigma^%s は I のスカラー倍ではない" % (a, b))

# 追加: 3 式 sigma^a sigma^a = I が「全部同じ行列だから」ではないこと
rep.truth(float(np.max(np.abs(loc['x'] - loc['y']))) > _sage_const_0p5 , "(d) sigma^x != sigma^y")
rep.truth(float(np.max(np.abs(loc['y'] - loc['z']))) > _sage_const_0p5 , "(d) sigma^y != sigma^z")
rep.truth(float(np.max(np.abs(loc['z'] - loc['x']))) > _sage_const_0p5 , "(d) sigma^z != sigma^x")

rep.finish()

